//! Only necessary guard/failure tests. Fixed DTOs below are input mutations,
//! never a live peer, Server ready artifact, authenticated session or SQL result.
use super::{native_navigation_runner as runner,application_protocol as app,equipment as gear,world_protocol as world,transport as tls};
use std::{fs,path::Path,time::{Duration,Instant},net::SocketAddr};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
fn captures()->Value{let root=Path::new(env!("CARGO_MANIFEST_DIR"));let p:Value=serde_json::from_slice(&fs::read(root.join("logs/continuation-20261003/r437-navigation-snapshot.json")).unwrap()).unwrap();serde_json::from_slice(&fs::read(Path::new(p["replay"]["root"].as_str().unwrap()).join("navigation-tls-capture.json")).unwrap()).unwrap()}
fn response(seq:u64)->app::Response{let c=captures();let row=c["entries"].as_array().unwrap().iter().find(|e|e["sequence"]==seq).unwrap();let s=row["response_hex"].as_str().unwrap();let b:Vec<_>=(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect();app::decode_response_version(&b,26).unwrap().response}
fn g(seq:u64)->gear::Reply{let app::Response::Equipment(v)=response(seq)else{panic!()};v}
fn scope()->runner::Scope{runner::Scope{context:app::SelectionContext{key:app::CharacterKey{source_id:7,object_id:10275},epoch:0x8000000000000000},channel:0}}
fn w()->world::Reply{let c=captures();for e in c["entries"].as_array().unwrap(){if e["response_kind"]!=21{continue;}let app::Response::World(v)=response(e["sequence"].as_u64().unwrap())else{panic!()};if v.frame.as_ref().is_some_and(|f|f.phase==world::Phase::Loading){return v;}}panic!("fixed Loading input absent")}
fn plan()->runner::Plan{let der=vec![1,2,3];runner::Plan{endpoint:SocketAddr::from(([127,0,0,1],1)),server_name:"localhost".into(),ca_sha256:Sha256::digest(&der).into(),ca_der:der,sources:[7,42],object:10275,reselected_object:10163,initial_epoch:0x8000000000000000,channel:0,weapon:10304,armor:10305,map_id:564,manifest_digest:[1;32],total_timeout:Duration::from_secs(30),exchange_timeout:Duration::from_secs(2),prepare_timeout:Duration::from_secs(10),dto_ack_only:false}}
#[test]fn configuration_rejects_endpoint_trust_scope_and_unbounded_work_before_connect(){let mut p=plan();assert!(p.validate().is_ok());p.endpoint=SocketAddr::from(([192,0,2,1],1000));assert_eq!(p.validate().unwrap_err().code,"loopback_endpoint_required");let mut p=plan();p.ca_der[0]^=1;assert_eq!(p.validate().unwrap_err().code,"pinned_CA");let mut p=plan();p.initial_epoch=u64::MAX-1;assert!(p.validate().is_err());let mut p=plan();p.sources=[42,7];assert!(p.validate().is_err());let mut p=plan();p.total_timeout=Duration::from_secs(46);assert!(p.validate().is_err());let mut p=plan();p.exchange_timeout=Duration::from_millis(49);assert!(p.validate().is_err());}
#[test]fn full_CAS_guard_refuses_foreign_baseline_revision_and_unrelated_flag_changes(){let a=runner::verify_gear(&g(9),scope()).unwrap();let b=runner::verify_gear(&g(10),scope()).unwrap();runner::verify_CAS(&a,&b,10304,false,true).unwrap();let mut bad=b.clone();bad.revision=a.revision;assert!(runner::verify_CAS(&a,&bad,10304,false,true).is_err());let mut bad=b.clone();bad.flags[0].equipped=!bad.flags[0].equipped;assert!(runner::verify_CAS(&a,&bad,10304,false,true).is_err());let mut bad=b.clone();std::sync::Arc::make_mut(&mut bad.source).context.epoch+=1;assert!(runner::verify_CAS(&a,&bad,10304,false,true).is_err());assert!(runner::verify_CAS(&a,&b,10304,false,false).is_err());let mut bad=a.clone();bad.modifiers[0]+=1;assert!(runner::verify_isolation(&a,&bad).is_err());let mut bad=g(9);bad.request.context.key.source_id=42;assert!(runner::verify_gear(&bad,scope()).is_err());}
#[test]fn selected_owner_epoch_channel_and_phase_must_match_each_live_step(){let app::Response::Navigation(v)=response(5)else{panic!()};let s=scope();runner::verify_navigation(&v,s,app::NavigationPhase::Lobby).unwrap();let mut bad=v.clone();bad.context.epoch+=1;assert!(runner::verify_navigation(&bad,s,app::NavigationPhase::Lobby).is_err());let mut bad=v.clone();bad.context.key.source_id=42;assert!(runner::verify_navigation(&bad,s,app::NavigationPhase::Lobby).is_err());let mut bad=v.clone();bad.snapshot.channel_id=Some(1);assert!(runner::verify_navigation(&bad,s,app::NavigationPhase::Lobby).is_err());assert!(runner::verify_navigation(&v,s,app::NavigationPhase::Characters).is_err());}
#[test]fn world_fence_rejects_stale_generation_revision_resource_and_phase(){let v=w();let f=v.frame.as_ref().unwrap();let mut fence=runner::WorldFence::new(scope());fence.accept(&v,564,f.manifest.digest).unwrap();let mut bad=v.clone();bad.frame.as_mut().unwrap().generation+=1;assert!(fence.accept(&bad,564,f.manifest.digest).is_err());let mut bad=v.clone();bad.frame.as_mut().unwrap().revision-=1;assert!(fence.accept(&bad,564,f.manifest.digest).is_err());let mut bad=v.clone();bad.echo.context.epoch+=1;assert!(fence.accept(&bad,564,f.manifest.digest).is_err());assert!(fence.accept(&v,564,[1;32]).is_err());let mut bad=v.clone();bad.frame.as_mut().unwrap().phase=world::Phase::Preparing;assert!(fence.accept(&bad,564,f.manifest.digest).is_err());}
#[test]fn expiry_needs_query_valid_intent_same_challenge_and_real_active_backend(){let c=runner::ExpiryChallenge{token:"fixture-operation-not-authority".into(),scope:scope(),item:10304,gear_revision:4};let e=runner::ExpiryObservation{token:c.token.clone(),scope:c.scope,item:10304,gear_revision:4,query_started_millis:10000,cutoff_exclusive:11000,provider_finished_millis:11001,backend_remaining_nanos:2_000_000_000,actual_wall_clock:true,selected_owner_registration:true};runner::verify_expiry(&c,&e).unwrap();let mut bad=e.clone();bad.provider_finished_millis=10999;assert!(runner::verify_expiry(&c,&bad).is_err());let mut bad=e.clone();bad.scope.context.epoch+=1;assert!(runner::verify_expiry(&c,&bad).is_err());let mut bad=e.clone();bad.gear_revision=3;assert!(runner::verify_expiry(&c,&bad).is_err());let mut bad=e.clone();bad.actual_wall_clock=false;assert!(runner::verify_expiry(&c,&bad).is_err());let mut bad=e.clone();bad.backend_remaining_nanos=0;assert!(runner::verify_expiry(&c,&bad).is_err());}
struct NeverControl;
impl runner::Control for NeverControl{fn arm_expiry(&mut self,_:runner::Scope,_:u64,_:i64,_:Instant)->std::result::Result<runner::ExpiryChallenge,runner::Fault>{panic!("must fail before control") }fn expiry_observation(&mut self,_:&runner::ExpiryChallenge,_:Instant)->std::result::Result<runner::ExpiryObservation,runner::Fault>{panic!("must fail before control")}}
#[test]fn cancelled_runner_redacts_failures_and_reports_cleanup_separately(){let cancel=tls::Cancellation::new();cancel.cancel();let secret="credential-canary-never-log";let mut creds=||app::Credentials::new(secret.into(),secret.into()).map_err(|_|runner::Fault{step:"credentials",code:"configuration_rejected"});let report=runner::run_live(&plan(),&mut creds,&mut NeverControl,cancel);assert_eq!(report.failure.as_ref().unwrap().code,"cancelled");assert_eq!(report.TLS_connections_opened,0);assert_eq!(report.TLS_connections_closed,0);assert!(!report.success());let out=serde_json::to_string(&report).unwrap();assert!(!out.contains(secret));assert!(!out.contains("request_hex"));assert!(!out.contains("AUTHraw"));let mut r=runner::Report::default();r.completed=true;r.TLS_connections_opened=2;r.TLS_connections_closed=2;assert!(r.success());r.cleanup_errors.push(runner::Fault{step:"TLS_close",code:"timeout"});assert!(!r.success());fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r438-runner-local-boundaries.json"),serde_json::to_vec_pretty(&json!({"state":"LOCAL_RUNNER_GUARDS_ONLY_NO_LIVE_ENDPOINT","configuration_before_connect":true,"full_CAS_flags_revision_source":true,"owner_epoch_channel_phase":true,"world_generation_revision_resource_phase":true,"expiry_actual_control_required":true,"cancel_before_AUTH":true,"secret_redaction":true,"cleanup_errors_not_hidden":true,"Rust_live_SQL_TLS":false,"renderer_LOADED":false,"GUI":0,"report":report})).unwrap()).unwrap();}
